/* FDK EmpowerNet · the-new-economics-of-european-banking-power · ES — generated by scripts/i18n-build.mjs. Do not edit by hand. */
window.FDK_I18N=window.FDK_I18N||{};window.FDK_I18N.es=window.FDK_I18N.es||{};
Object.assign(window.FDK_I18N.es,{"<strong>1. UniCredit</strong> — continental scale, geographic diversification, optionality; risk: political resistance and integration economics.":"<strong>1. UniCredit</strong>: escala continental, diversificación geográfica, opcionalidad; riesgo: resistencia política y economía de la integración.","<strong>2. Intesa Sanpaolo</strong> — strong domestic franchise and enhanced consolidation; risk: fiscal burden, antitrust, integration.":"<strong>2. Intesa Sanpaolo</strong>: sólida franquicia nacional y consolidación reforzada; riesgo: carga fiscal, competencia, integración.","<strong>3. Crédit Agricole</strong> — diversified European earnings and Italian exposure; risk: capital efficiency and transaction structure.":"<strong>3. Crédit Agricole</strong>: beneficios europeos diversificados y exposición a Italia; riesgo: eficiencia del capital y estructura de la operación.","<strong>4. Unipol / BPER</strong> — financed restructuring and distribution synergies; risk: execution, capital, domestic fiscal exposure.":"<strong>4. Unipol / BPER</strong>: reestructuración financiada y sinergias de distribución; riesgo: ejecución, capital, exposición fiscal nacional.","<strong>5. Banco BPM</strong> — strategic scarcity and possible future combination; risk: uncertain timing and valuation.":"<strong>5. Banco BPM</strong>: escasez estratégica y posible combinación futura; riesgo: incertidumbre sobre el calendario y la valoración.","<strong>6. Generali / Banca Generali</strong> — insurance and wealth franchises; risk: ownership uncertainty and premium volatility.":"<strong>6. Generali / Banca Generali</strong>: negocios de seguros y gestión patrimonial; riesgo: incertidumbre accionarial y volatilidad de las primas.","<strong>7. MPS / Mediobanca</strong> — event-driven opportunities; risk: offer terms, regulatory outcomes, limited standalone optionality.":"<strong>7. MPS / Mediobanca</strong>: oportunidades ligadas a operaciones corporativas; riesgo: condiciones de la oferta, resultados regulatorios, limitada opcionalidad en solitario.","<strong>Crédit Agricole</strong> reported €7.65 billion of nine-month net income, up 13.7%, holding roughly 29.3% of Banco BPM.":"<strong>Crédit Agricole</strong> registró un beneficio neto de 7.650 millones de euros en nueve meses, un 13,7 % más, y mantiene alrededor del 29,3 % de Banco BPM.","<strong>Crédit Agricole–Banco BPM and Generali</strong> — any new statements on strategic alternatives or governance.":"<strong>Crédit Agricole–Banco BPM y Generali</strong>: cualquier nueva declaración sobre alternativas estratégicas o gobernanza.","<strong>Delfin</strong> — any confirmation, rejection or modification of the reported proposal.":"<strong>Delfin</strong>: cualquier confirmación, rechazo o modificación de la propuesta de la que se ha informado.","<strong>Intesa confirmed</strong> its MPS offer proceeds, targeting about €2.9 billion in run-rate synergies by 2029 and a possible mandatory Mediobanca offer.":"<strong>Intesa confirmó</strong> que su oferta sobre MPS sigue adelante, con el objetivo de unos 2.900 millones de euros de sinergias recurrentes en 2029 y una posible oferta obligatoria sobre Mediobanca.","<strong>Intesa–MPS</strong> — offer-document approval, tender timetable, antitrust remedies, and Q3 results on November 3.":"<strong>Intesa–MPS</strong>: aprobación del folleto de la oferta, calendario de la opa, remedios antimonopolio y resultados del tercer trimestre el 3 de noviembre.","<strong>Italian banking taxation</strong> — clarity on the IRES increase, deferred-tax treatment and the split of the €5.8 billion between banks and insurers.":"<strong>Fiscalidad bancaria italiana</strong>: claridad sobre el aumento del IRES, el tratamiento de los impuestos diferidos y el reparto de los 5.800 millones de euros entre bancos y aseguradoras.","<strong>Italy's draft 2027 budget</strong> sets €5.8 billion in contributions from banks and insurers, raising the bank corporate tax rate from 27.5% to 30.5%.":"<strong>El proyecto de presupuestos de Italia para 2027</strong> fija 5.800 millones de euros en contribuciones de bancos y aseguradoras y eleva el tipo del impuesto de sociedades bancario del 27,5 % al 30,5 %.","<strong>MPS shareholders rejected</strong> the Banco BPM and Banca Generali acquisitions and the Mediobanca merger, with roughly 91% of votes against.":"<strong>Los accionistas de MPS rechazaron</strong> las adquisiciones de Banco BPM y Banca Generali y la fusión con Mediobanca, con alrededor del 91 % de los votos en contra.","<strong>Monday's dashboard</strong> — domestic versus diversified bank performance, MPS offer spreads, earnings revisions, Italian sovereign spreads and expected distributions.":"<strong>El panel del lunes</strong>: comportamiento de los bancos nacionales frente a los diversificados, diferenciales de la oferta sobre MPS, revisiones de beneficios, diferenciales soberanos italianos y distribuciones previstas.","<strong>The central risk</strong> is shifting from failure to complete acquisitions toward failure to realize their expected economic benefits.":"<strong>El riesgo central</strong> se desplaza del fracaso en completar las adquisiciones al fracaso en materializar sus beneficios económicos esperados.","<strong>UniCredit</strong> expects to hold about 50% of Commerzbank voting rights around year-end after ECB authorization to cross 30%.":"<strong>UniCredit</strong> prevé tener alrededor del 50 % de los derechos de voto de Commerzbank hacia final de año, tras la autorización del BCE para superar el 30 %.","<strong>UniCredit–Commerzbank</strong> — German stakeholder responses, regulatory developments and integration structure.":"<strong>UniCredit–Commerzbank</strong>: respuestas de los grupos de interés alemanes, novedades regulatorias y estructura de integración.","Acquisitions remain viable but remedies, political objections and higher integration costs reduce returns. Investors raise required returns, transaction discounts widen, dividends become cautious, and standalone, diversified banks may outperform. (Previous: 20%.)":"Las adquisiciones siguen siendo viables, pero los remedios, las objeciones políticas y los mayores costes de integración reducen la rentabilidad. Los inversores elevan la rentabilidad exigida, los descuentos de las operaciones se amplían, los dividendos se vuelven prudentes y los bancos independientes y diversificados podrían obtener mejores resultados. (Anterior: 20 %.)","Consider a bank acquiring another with the expectation of €1 billion in annual pre-tax synergies. Those synergies have value only after taxation, integration costs, capital requirements and execution risk. If the effective tax burden rises, the net present value of those synergies falls, all else equal.":"Considere un banco que adquiere otro con la expectativa de obtener 1.000 millones de euros en sinergias anuales antes de impuestos. Esas sinergias solo tienen valor después de impuestos, costes de integración, requisitos de capital y riesgo de ejecución. Si la carga fiscal efectiva aumenta, el valor actual neto de esas sinergias disminuye, en igualdad de condiciones.","Crédit Agricole–Banco BPM — strategic influence":"Crédit Agricole–Banco BPM: influencia estratégica","European markets were closed on Sunday, November 1, so no session has yet priced the budget details. The immediate implications are nonetheless clear. Italy's intervention may alter normalized earnings, with domestically concentrated banks facing a larger direct effect than internationally diversified groups. The valuation of synergies must shift from announced pre-tax figures to risk-adjusted, after-tax net present value.":"Los mercados europeos estuvieron cerrados el domingo 1 de noviembre, por lo que ninguna sesión ha descontado aún los detalles de los presupuestos. Las implicaciones inmediatas son, no obstante, claras. La intervención de Italia puede alterar los beneficios normalizados, y los bancos concentrados en el mercado nacional afrontan un efecto directo mayor que los grupos diversificados internacionalmente. La valoración de las sinergias debe pasar de las cifras anunciadas antes de impuestos a un valor actual neto ajustado por riesgo y después de impuestos.","Fiscal and regulatory friction delays value":"La fricción fiscal y regulatoria retrasa el valor","Generali–Banca Generali — a capital-allocation issue":"Generali–Banca Generali: una cuestión de asignación de capital","In Brussels, the Commission has continued to challenge Italy's Golden Power framework, pressing Rome for further changes (Reuters, March 2026). Europe cannot establish a fully effective Banking Union through prudential integration alone if regulatory intervention and fiscal treatment remain materially fragmented. The ECB has granted prudential authorizations for both the Intesa–MPS and UniCredit–Commerzbank transactions — but regulatory feasibility is a condition of execution, not proof of value creation. UniCredit's Commerzbank strategy still confronts German concerns over industrial sovereignty, with the Commission's competition review carrying a reported November 16 deadline.":"En Bruselas, la Comisión ha seguido cuestionando el régimen italiano del Golden Power y presiona a Roma para introducir nuevos cambios (Reuters, marzo de 2026). Europa no puede establecer una Unión Bancaria plenamente eficaz solo mediante la integración prudencial si la intervención regulatoria y el tratamiento fiscal siguen sustancialmente fragmentados. El BCE ha concedido autorizaciones prudenciales tanto para la operación Intesa–MPS como para UniCredit–Commerzbank, pero la viabilidad regulatoria es una condición para la ejecución, no una prueba de creación de valor. La estrategia de UniCredit en Commerzbank sigue chocando con la preocupación alemana por la soberanía industrial, y la revisión de competencia de la Comisión tiene un plazo, según se ha informado, hasta el 16 de noviembre.","In Focus":"En foco","Intesa Sanpaolo — execution discipline":"Intesa Sanpaolo: disciplina de ejecución","Intesa completes MPS subject to approvals; Unipol advances; UniCredit progresses toward control of Commerzbank; Crédit Agricole holds its Banco BPM position; fiscal measures are enacted broadly as framed with parliamentary adjustments. Consolidation premiums become more selective and capital efficiency gains importance. (Previous: 70%.)":"Intesa completa MPS, sujeto a aprobaciones; Unipol avanza; UniCredit progresa hacia el control de Commerzbank; Crédit Agricole mantiene su posición en Banco BPM; las medidas fiscales se aprueban en líneas generales tal como se plantearon, con ajustes parlamentarios. Las primas de consolidación se vuelven más selectivas y la eficiencia del capital gana importancia. (Anterior: 70 %.)","Intesa has reaffirmed its MPS offer, holds required sectoral authorizations including ECB prudential approval, and plans to sell a substantial MPS perimeter to Unipol. It targets about €2.9 billion in run-rate synergies by 2029 — a management target, not a realized result. The added fiscal burden challenges the value-creation equation; watch post-tax earnings and distribution assumptions. Principal uncertainty: antitrust remedies, transaction costs and translating projected synergies into realized returns.":"Intesa ha reafirmado su oferta sobre MPS, cuenta con las autorizaciones sectoriales necesarias, incluida la aprobación prudencial del BCE, y prevé vender un perímetro sustancial de MPS a Unipol. Su objetivo es alcanzar unos 2.900 millones de euros de sinergias recurrentes en 2029, un objetivo de la dirección, no un resultado obtenido. La carga fiscal adicional pone en cuestión la ecuación de creación de valor; atención a los beneficios después de impuestos y a las hipótesis de distribución. Principal incertidumbre: remedios antimonopolio, costes de la operación y la conversión de las sinergias previstas en rentabilidad efectiva.","Intesa's expected annual run-rate synergies by 2029":"sinergias anuales recurrentes previstas por Intesa en 2029","Intesa–MPS":"Intesa–MPS","Italy taxes the profits of consolidation just as the industrial race for scale accelerates across Intesa, UniCredit and Crédit Agricole. The Velocity Edge, by Francesco De Leo Kaufmann.":"Italia grava los beneficios de la consolidación justo cuando se acelera la carrera industrial por la escala de Intesa, UniCredit y Crédit Agricole. The Velocity Edge, por Francesco De Leo Kaufmann.","Italy's banking consolidation has entered a more consequential phase. Just as shareholders are clearing the way for the creation of larger financial institutions, the Italian government is increasing its claim on the profits those institutions are expected to generate. The result is a fundamental change in the economics of consolidation.":"La consolidación bancaria italiana ha entrado en una fase de mayores consecuencias. Justo cuando los accionistas despejan el camino a la creación de entidades financieras más grandes, el Gobierno italiano aumenta su participación en los beneficios que se espera que generen esas entidades. El resultado es un cambio fundamental en la economía de la consolidación.","Italy's banking consolidation now sits at the intersection of capital concentration, fiscal intervention and continental competition. Europe's fundamental question remains unanswered: can it build globally competitive financial institutions while maintaining fragmented national approaches to taxation, strategic control and industrial sovereignty? <span class=\"hl-green\">The next banking premium will belong not to those who accumulate the most assets, but to those who generate the highest sustainable returns from the capital they control.</span>":"La consolidación bancaria italiana se sitúa ahora en la intersección de la concentración de capital, la intervención fiscal y la competencia continental. La pregunta fundamental de Europa sigue sin respuesta: ¿puede construir entidades financieras competitivas a escala mundial mientras mantiene enfoques nacionales fragmentados en materia de fiscalidad, control estratégico y soberanía industrial? <span class=\"hl-green\">La próxima prima bancaria no corresponderá a quienes acumulen más activos, sino a quienes generen la mayor rentabilidad sostenible del capital que controlan.</span>","Just as shareholders clear the way for larger banks, Rome is <strong>increasing its claim</strong> on the profits those banks are expected to generate — a <span class=\"hl-green\">fundamental change in the economics of consolidation</span>.":"Justo cuando los accionistas despejan el camino a bancos más grandes, Roma <strong>aumenta su participación</strong> en los beneficios que se espera que generen esos bancos: un <span class=\"hl-green\">cambio fundamental en la economía de la consolidación</span>.","MPS shareholder votes against the proposed deals":"votos de los accionistas de MPS en contra de las operaciones propuestas","MPS–Mediobanca — diminishing independence":"MPS–Mediobanca: independencia menguante","On October 30, Unipol confirmed full subscription of its roughly €2.5 billion rights issue, supporting the planned acquisition of the agreed MPS perimeter; it has authorization to acquire de facto control of BPER. The financing strengthens credibility, but value depends on final assets, acquisition economics and integration — with the new fiscal measures an added consideration.":"El 30 de octubre, Unipol confirmó la suscripción íntegra de su ampliación de capital de aproximadamente 2.500 millones de euros, que respalda la adquisición prevista del perímetro acordado de MPS; cuenta con autorización para adquirir el control de facto de BPER. La financiación refuerza la credibilidad, pero el valor depende de los activos finales, la economía de la adquisición y la integración, con las nuevas medidas fiscales como factor adicional.","On consolidation, no verified corporate announcement dated October 31 or November 1 reverses the prior developments. On October 29, MPS shareholders rejected the proposed acquisitions of Banco BPM and Banca Generali, and the merger of Mediobanca into MPS, with roughly 91% against. On October 30, Intesa confirmed its offer for MPS would proceed, waiving the condition tied to the failed Mediobanca merger, and noting a successful acquisition could trigger a mandatory offer for remaining Mediobanca shares. The battle for an independent MPS-centered third pole has lost its principal shareholder-supported strategy — though competition review, offer-document approval and shareholder acceptance remain outstanding.":"En cuanto a la consolidación, ningún anuncio corporativo verificado fechado el 31 de octubre o el 1 de noviembre revierte los acontecimientos anteriores. El 29 de octubre, los accionistas de MPS rechazaron las adquisiciones propuestas de Banco BPM y Banca Generali, así como la fusión de Mediobanca en MPS, con alrededor del 91 % en contra. El 30 de octubre, Intesa confirmó que su oferta sobre MPS seguirá adelante, renunciando a la condición vinculada a la fallida fusión con Mediobanca, y señaló que una adquisición exitosa podría activar una oferta obligatoria por las restantes acciones de Mediobanca. La batalla por un tercer polo independiente en torno a MPS ha perdido su principal estrategia respaldada por los accionistas, aunque la revisión de competencia, la aprobación del folleto de la oferta y la aceptación de los accionistas siguen pendientes.","Reuters reported on October 29 that Czech investor Michal Strnad proposed acquiring Delfin for about €30 billion — an unconfirmed proposal, not a transaction. Control premiums turn volatile and governance uncertainty increases. (Unchanged.) The probability of orderly consolidation remains dominant, but the fiscal burden raises the risk that transactions proceed without delivering all the shareholder value originally anticipated.":"Reuters informó el 29 de octubre de que el inversor checo Michal Strnad propuso adquirir Delfin por unos 30.000 millones de euros, una propuesta no confirmada, no una operación. Las primas de control se vuelven volátiles y aumenta la incertidumbre sobre la gobernanza. (Sin cambios.) La probabilidad de una consolidación ordenada sigue siendo dominante, pero la carga fiscal eleva el riesgo de que las operaciones sigan adelante sin generar todo el valor para el accionista inicialmente previsto.","Rome's intervention exposes a tension: it wants a banking system strong enough to finance the economy and compete internationally, yet seeks additional revenues from highly profitable banks. Strategic independence cannot be strengthened indefinitely by taxing the capital that finances it.":"La intervención de Roma pone de manifiesto una tensión: quiere un sistema bancario lo bastante sólido para financiar la economía y competir internacionalmente, pero busca ingresos adicionales de bancos muy rentables. La independencia estratégica no puede reforzarse indefinidamente gravando el capital que la financia.","Shareholders rejected the transactions meant to preserve MPS's independent perimeter. MPS is now valued chiefly through the probability and terms of Intesa's offer. Mediobanca remains significant for its investment banking, wealth management and Generali stake. Principal uncertainty: eventual ownership structure, minority treatment and the cost of any mandatory offer.":"Los accionistas rechazaron las operaciones destinadas a preservar el perímetro independiente de MPS. MPS se valora ahora sobre todo en función de la probabilidad y las condiciones de la oferta de Intesa. Mediobanca sigue siendo relevante por su banca de inversión, su gestión patrimonial y su participación en Generali. Principal incertidumbre: la estructura accionarial final, el trato a los minoritarios y el coste de cualquier oferta obligatoria.","The decisive question is no longer simply which banks will acquire competitors, control distribution networks or consolidate strategic shareholdings. It is whether the resulting institutions can generate sufficient incremental returns to compensate shareholders for acquisition costs, regulatory constraints, greater fiscal burdens and integration risks.":"La cuestión decisiva ya no es simplemente qué bancos adquirirán a sus competidores, controlarán redes de distribución o consolidarán participaciones estratégicas. Es si las entidades resultantes pueden generar una rentabilidad incremental suficiente para compensar a los accionistas por los costes de adquisición, las restricciones regulatorias, una mayor carga fiscal y los riesgos de integración.","The deeper struggle concerns who determines the allocation of European savings. Capital increasingly seeks continental efficiency while political legitimacy remains predominantly national. Ownership and economic control are becoming less synonymous; scale becomes a mechanism of independence only if it improves capital generation; and fiscal policy becomes a variable in competitiveness, since Europe lacks a harmonized banking-taxation framework. A banking acquisition changes ownership; a larger balance sheet changes funding capacity; but a change in the after-tax economics of capital can alter where institutions choose to deploy it. The next contest may concern not only who controls Europe's banks, but where those banks invest.":"La pugna de fondo se refiere a quién decide la asignación del ahorro europeo. El capital busca cada vez más la eficiencia continental, mientras la legitimidad política sigue siendo predominantemente nacional. La propiedad y el control económico son cada vez menos sinónimos; la escala solo se convierte en un mecanismo de independencia si mejora la generación de capital; y la política fiscal pasa a ser una variable de la competitividad, ya que Europa carece de un marco armonizado de fiscalidad bancaria. Una adquisición bancaria cambia la propiedad; un balance más grande cambia la capacidad de financiación; pero un cambio en la economía del capital después de impuestos puede alterar dónde deciden desplegarlo las entidades. La próxima pugna quizá no gire solo en torno a quién controla los bancos de Europa, sino a dónde invierten esos bancos.","The group reported €7.65 billion of nine-month 2026 net income, up 13.7%. Its ~29.3% Banco BPM stake contributed €106 million via equity accounting in Q3; Crédit Agricole Italia added €174 million. It can influence Banco BPM's future without an immediate full acquisition, and its European earnings base diversifies against Italian-specific taxation. Principal uncertainty: valuation, governance and the rationale of any future combination.":"El grupo registró un beneficio neto de 7.650 millones de euros en los nueve primeros meses de 2026, un 13,7 % más. Su participación de ~29,3 % en Banco BPM aportó 106 millones de euros por puesta en equivalencia en el tercer trimestre; Crédit Agricole Italia sumó 174 millones de euros. Puede influir en el futuro de Banco BPM sin una adquisición completa inmediata, y su base de beneficios europea le ofrece diversificación frente a la fiscalidad específica italiana. Principal incertidumbre: valoración, gobernanza y lógica de cualquier combinación futura.","The market may begin rewarding geographic diversification more explicitly — but only where it improves risk-adjusted capital productivity. Event-driven valuations remain exposed to transaction mechanics: the MPS offer spread, potential Mediobanca mandatory-offer terms, Banco BPM's probability-weighted transaction value, and the incremental value of banking assets for Unipol and BPER against the capital required. The market is moving from rewarding consolidation announcements toward testing after-tax execution economics.":"El mercado puede empezar a premiar de forma más explícita la diversificación geográfica, pero solo cuando mejore la productividad del capital ajustada por riesgo. Las valoraciones ligadas a operaciones siguen expuestas a la mecánica de las transacciones: el diferencial de la oferta sobre MPS, las posibles condiciones de una oferta obligatoria sobre Mediobanca, el valor de la operación de Banco BPM ponderado por probabilidad y el valor incremental de los activos bancarios para Unipol y BPER frente al capital necesario. El mercado está pasando de premiar los anuncios de consolidación a poner a prueba la economía de la ejecución después de impuestos.","The most important new information comes from Italy's draft 2027 budget, reported on October 31. The proposed contribution from banks and insurers is estimated at €5.8 billion in 2027, including a three-percentage-point increase in the additional IRES burden for 2027 and 2028, changes affecting deferred tax assets, and a doubling of specified financial transaction tax rates. For banks, the relevant corporate tax rate would rise from 27.5% to 30.5%, per measures announced when the government approved the budget on October 28. The bill must still pass Parliament.":"La información nueva más relevante procede del proyecto de presupuestos de Italia para 2027, dado a conocer el 31 de octubre. La contribución propuesta de bancos y aseguradoras se estima en 5.800 millones de euros en 2027, incluido un aumento de tres puntos porcentuales del recargo adicional del IRES para 2027 y 2028, cambios que afectan a los activos por impuestos diferidos y la duplicación de los tipos de determinados impuestos sobre transacciones financieras. Para los bancos, el tipo del impuesto de sociedades aplicable pasaría del 27,5 % al 30,5 %, según las medidas anunciadas cuando el Gobierno aprobó los presupuestos el 28 de octubre. El proyecto aún debe ser aprobado por el Parlamento.","The next phase of European consolidation will reward institutions able to increase returns on capital faster than governments, regulators and integration costs absorb those returns.":"La próxima fase de la consolidación europea premiará a las entidades capaces de aumentar la rentabilidad del capital más deprisa de lo que gobiernos, reguladores y costes de integración absorben esa rentabilidad.","The rejected Banca Generali acquisition removes one restructuring route. On October 27, Intesa CEO Carlo Messina said the bank intends to protect Generali's independence and will cooperate with other significant shareholders. Assess Generali through insurance profitability, capital generation and distributions; treat ownership developments as an added variable.":"El rechazo de la adquisición de Banca Generali elimina una vía de reestructuración. El 27 de octubre, el consejero delegado de Intesa, Carlo Messina, afirmó que el banco pretende proteger la independencia de Generali y cooperará con otros accionistas significativos. Evalúe Generali por su rentabilidad aseguradora, su generación de capital y sus distribuciones; trate la evolución accionarial como una variable adicional.","The sector is confronting two simultaneous transitions. The first is industrial: institutions seeking scale through acquisitions, distribution, wealth management and insurance. The second is financial: governments, supervisors and markets reassessing how much value shareholders retain from the profitability of larger institutions. These can reinforce each other — or conflict.":"El sector afronta dos transiciones simultáneas. La primera es industrial: entidades que buscan escala mediante adquisiciones, distribución, gestión patrimonial y seguros. La segunda es financiera: gobiernos, supervisores y mercados reevalúan cuánto valor conservan los accionistas de la rentabilidad de entidades más grandes. Ambas pueden reforzarse mutuamente o entrar en conflicto.","These are proposed legislation, not enacted law. The €5.8 billion must not be treated as a uniform reduction in bank earnings or attributed entirely to listed banks: corporate income tax affects after-tax earnings, deferred-tax measures change the timing of cash taxes, and transaction taxes raise trading costs. The new investment question is how much of the burden will be absorbed by earnings, distributions, customers and valuations.":"Se trata de legislación propuesta, no aprobada. Los 5.800 millones de euros no deben tratarse como una reducción uniforme de los beneficios bancarios ni atribuirse íntegramente a los bancos cotizados: el impuesto de sociedades afecta al beneficio después de impuestos, las medidas sobre impuestos diferidos cambian el calendario de los pagos de impuestos en efectivo y los impuestos sobre transacciones elevan los costes de negociación. La nueva cuestión de inversión es qué parte de la carga absorberán los beneficios, las distribuciones, los clientes y las valoraciones.","This creates a new distinction: Accounting Scale — assets, deposits, branches, reported revenue — can be acquired. Economic Scale — sustainable earnings, capital efficiency and shareholder returns after all costs — must be earned.":"Esto crea una nueva distinción: la escala contable —activos, depósitos, sucursales, ingresos declarados— puede adquirirse. La escala económica —beneficios sostenibles, eficiencia del capital y rentabilidad para el accionista después de todos los costes— debe ganarse.","UniCredit received ECB authorization on October 15 to cross 30% without an upper limit, and expects roughly 50% of voting rights around year-end. On October 30 it presented commitments to Germany's Mittelstand, seeking industrial legitimacy. Its structural advantage is geographic diversification, reducing reliance on any single national fiscal environment — though cross-border integration adds political and operational risk. Principal uncertainty: whether control converts into an economically effective combination accepted by German stakeholders.":"UniCredit recibió el 15 de octubre la autorización del BCE para superar el 30 % sin límite superior y prevé alcanzar aproximadamente el 50 % de los derechos de voto hacia final de año. El 30 de octubre presentó compromisos con el Mittelstand alemán en busca de legitimidad industrial. Su ventaja estructural es la diversificación geográfica, que reduce la dependencia de un único entorno fiscal nacional, aunque la integración transfronteriza añade riesgo político y operativo. Principal incertidumbre: si el control se traduce en una combinación económicamente eficaz y aceptada por los grupos de interés alemanes.","UniCredit–Commerzbank":"UniCredit–Commerzbank","UniCredit–Commerzbank — continental scale":"UniCredit–Commerzbank: escala continental","Unipol–BPER — a financed route":"Unipol–BPER: una vía financiada","bank corporate tax rate under the draft budget":"tipo del impuesto de sociedades bancario según el proyecto de presupuestos","proposed 2027 contribution from banks and insurers":"contribución propuesta de bancos y aseguradoras para 2027","qualitative ranking, not a buy recommendation":"clasificación cualitativa, no es una recomendación de compra","reopening Monday, November 2":"reapertura el lunes 2 de noviembre","the last 24 hours":"las últimas 24 horas","“The next premium belongs not to those who accumulate the most assets, but to those who generate the highest sustainable returns from the capital they control.”":"«La próxima prima no corresponde a quienes acumulan más activos, sino a quienes generan la mayor rentabilidad sostenible del capital que controlan.»"});
